class Solution {
public:
    long long countSubarrays(std::vector<int>& nums) {
        long long total = 0;
        long long cur_len = 0;
        for (int i = 0; i < (int)nums.size(); i++) {
            if (i > 0 && nums[i] > nums[i - 1]) {
                cur_len++;
            } else {
                cur_len = 1;
            }
            total += cur_len;
        }
        return total;
    }
};

class Solution {
    public long countSubarrays(int[] nums) {
        long total = 0;
        long curLen = 0;
        for (int i = 0; i < nums.length; i++) {
            if (i > 0 && nums[i] > nums[i - 1]) {
                curLen++;
            } else {
                curLen = 1;
            }
            total += curLen;
        }
        return total;
    }
}

